package edu.pe.cibertec.saibm.inventario.infrastructure.persistence; import java.util.*; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface StockJpaRepository extends JpaRepository<StockJpaEntity,String>{@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select s from StockJpaEntity s where s.bookId=:id")Optional<StockJpaEntity> findForUpdate(@Param("id")String id);}
